const tilePalette=['#487bd5','#17a398','#9969bf','#df9851','#5c9db2','#d47389'];
let activityPage=0;

const actionPalette=['#386cab','#278980','#9469ac','#b88249','#4d879d','#b2657d','#6c7899','#709068','#ab744f','#7377ac'];const actionColors={deposit:'#4777aa',withdraw:'#b48551',create:'#9170ad',sale:'#638b71',cancel:'#b56e82',swap:'#318d88',wrap:'#5a9ab5',unlock:'#8c925a',unwrap:'#6684a0',bid:'#a58c45',deploy:'#787cb0',refund:'#bc806b',unstake:'#957b66',de_collateralised:'#6e8793',remove_liquidity:'#9b7693',update_interest:'#668d82',add_liquidity:'#9a6c69',approve:'#698661',bridge:'#678e9b',redeem:'#9b7b98'};const actionColor=k=>k?(actionColors[k]||actionPalette[Math.max(0,labels().findIndex(l=>l.id===k))%actionPalette.length]):'#a5aebb';
const txDate=t=>t.state.transaction.timestamp.slice(0,10);
function openEvidence(id){activeLabels=[];exactCombination=null;selected=id;$('#search').value='';$('#error-filter').value='all';changeView('connection');window.scrollTo({top:0,behavior:'smooth'});}
function renderDistribution(){const counts=frequencies(),sorted=labels().filter(l=>counts[l.id]).sort((a,b)=>counts[b.id]-counts[a.id]),top=sorted.slice(0,6),keys=top.map(l=>l.id),total=rows().length,max=counts[sorted[0]?.id]||1;
 $('#ranking').innerHTML=sorted.map(l=>`<button class="rank-row ${activeLabels.includes(l.id)?'active':''}" data-rank="${l.id}"><span>${esc(l.label)}</span><span class="rank-track"><i style="width:${counts[l.id]/max*100}%;background:${actionColor(l.id)}"></i></span><span>${counts[l.id]} · ${Math.round(counts[l.id]/total*100)}%</span></button>`).join('')||'<p class="small">Other transactions.</p>';
 document.querySelectorAll('[data-rank]').forEach(b=>b.onclick=()=>setLabels(activeLabels[0]===b.dataset.rank?[]:[b.dataset.rank]));
 $('#mosaic-legend').innerHTML=top.map((l,i)=>`<span class="mosaic-key"><i style="background:${actionColor(l.id)}"></i>${esc(l.label)}</span>`).join('')+'<span class="mosaic-key"><i style="background:#9ba6b6"></i>Other actions</span><span class="mosaic-key"><i style="background:#e5eaf0"></i>Other transactions</span>';
 const ordered=[...rows()].sort((a,b)=>txDate(a).localeCompare(txDate(b))||a.state.transaction.block_number-b.state.transaction.block_number);
 $('#mosaic').innerHTML=ordered.map(t=>{const tags=chosen(t),cs=tags.map(k=>keys.includes(k)?actionColor(k):'#9ba6b6');const bg=cs.length?`linear-gradient(90deg,${cs.map((c,i)=>`${c} ${i/cs.length*100}% ${(i+1)/cs.length*100}%`).join(',')})`:'#e5eaf0';return `<button class="tx-tile ${activeLabels.length&&(!activeLabels.every(k=>tags.includes(k))||exactCombination&&[...tags].sort().join('|')!==exactCombination)?'dim':''}" data-tile="${t.id}" aria-label="${esc(txDate(t)+' · '+(tags.map(name).join(', ')||'Other transactions')+' · '+short(t.id))}" style="background:${bg}"></button>`}).join('');document.querySelectorAll('[data-tile]').forEach(b=>{b.onclick=()=>openEvidence(b.dataset.tile);tooltip(b,b.getAttribute('aria-label'))});
 $('#mosaic-summary').textContent=`${total} transactions · ${rows().filter(t=>chosen(t).length>1).length} multi-action · ${rows().filter(t=>!chosen(t).length).length} without classified actions`;
}
function periodStart(date,unit){let d=new Date(date+'T00:00:00Z');if(unit==='month')d.setUTCDate(1);if(unit==='week')d.setUTCDate(d.getUTCDate()-(d.getUTCDay()+6)%7);return d.toISOString().slice(0,10)}
function nextPeriod(date,unit){let d=new Date(date+'T00:00:00Z');if(unit==='month')d.setUTCMonth(d.getUTCMonth()+1);else d.setUTCDate(d.getUTCDate()+(unit==='week'?7:1));return d.toISOString().slice(0,10)}
function periodEnd(date,unit){return new Date(new Date(nextPeriod(date,unit)+'T00:00:00Z')-86400000).toISOString().slice(0,10)}
